#!/usr/bin/env php
<?php
/** Generate WP-CLI command documentation from the command catalog. */

declare( strict_types=1 );

use Saltus\WP\Framework\Features\WpCli\CommandCatalog;

$root = dirname( __DIR__ );
require_once $root . '/vendor/autoload.php';

$lines = [
	'# WP-CLI Reference',
	'',
	'<!-- This file is auto-generated by `composer docs:wpcli`. Do not edit by hand. -->',
	'',
	'Saltus exposes every WordPress-native MCP/Ability through an equivalent `wp saltus` command. Commands execute WordPress APIs and shared framework services directly; they do not make HTTP requests.',
	'',
	'## Output and JSON input',
	'',
	'List and detail commands support `--format=table|json|yaml`; table is the default. Commands accepting JSON support either an inline value or `@path/to/file.json`.',
	'',
	'## Commands',
	'',
	'| Ability | Command | Description |',
	'|---|---|---|',
];

foreach ( CommandCatalog::all() as $command ) {
	$markdown_command = str_replace( '|', '\\|', $command['command'] );
	$lines[]          = '| `' . $command['ability'] . '` | `' . $markdown_command . '` | ' . $command['description'] . ' |';
}

$lines = array_merge(
	$lines,
	[
		'',
		'## Examples',
		'',
		'```bash',
		'wp saltus model list --format=json',
		'wp saltus post create book "The Left Hand of Darkness" --status=draft --meta=\'{"isbn":"9780441478125"}\'',
		'wp saltus settings update book @settings.json',
		'wp saltus meta update book 42 @meta.json',
		'wp saltus reorder @order.json',
		'wp saltus post export 42 --file=book-42.xml',
		'```',
		'',
		'WP-CLI shell access is the authorization boundary. REST and MCP visibility gates do not hide CLI commands.',
		'',
	]
);

$contents = implode( "\n", $lines );
$target   = $root . '/docs/guides/wp-cli.md';
$current  = is_file( $target ) ? file_get_contents( $target ) : false;

if ( $current !== $contents ) {
	file_put_contents( $target, $contents );
}

echo 'Generated WP-CLI docs for ' . count( CommandCatalog::all() ) . " abilities.\n";
